import type { CSSProperties } from 'react';
import './upload-queue-preview.css';

export type UploadStatus =
  'queued' | 'uploading' | 'completed' | 'failed' | 'canceled';

export interface UploadItem {
  id: string;
  name: string;
  size: string;
  status: UploadStatus;
  /** 0–1 */
  progress: number;
  error?: string;
}

export interface UploadQueueProps {
  items: UploadItem[];
  onCancel: (id: string) => void;
  onRetry: (id: string) => void;
  className?: string;
}

const STATUS_TEXT: Record<UploadStatus, string> = {
  queued: 'Waiting',
  uploading: 'Uploading',
  completed: 'Done',
  failed: 'Failed',
  canceled: 'Canceled',
};

/**
 * A list of files moving through queued, uploading, done, failed or
 * canceled. Each state has its own icon shape and words, not only a color.
 * The component only draws; you own the uploads and pass in their state.
 */
export function UploadQueue({
  items,
  onCancel,
  onRetry,
  className = '',
}: UploadQueueProps) {
  return (
    <ul className={`mg-uploads ${className}`} aria-label='Uploads'>
      {items.map((item) => {
        const pct = Math.round(item.progress * 100);
        const busy = item.status === 'queued' || item.status === 'uploading';
        return (
          <li
            key={item.id}
            className='mg-uploads__item'
            data-status={item.status}
          >
            <span className='mg-uploads__icon' aria-hidden='true' />
            <div className='mg-uploads__body'>
              <div className='mg-uploads__row'>
                <strong>{item.name}</strong>
                <span>{item.size}</span>
              </div>
              <div
                className='mg-uploads__bar'
                role='progressbar'
                aria-label={`${item.name} upload`}
                aria-valuemin={0}
                aria-valuemax={100}
                aria-valuenow={pct}
                style={{ '--mg-progress': item.progress } as CSSProperties}
              >
                <span />
              </div>
              <span className='mg-uploads__state'>
                {STATUS_TEXT[item.status]}
                {item.status === 'uploading' ? ` · ${pct}%` : ''}
                {item.status === 'failed' && item.error
                  ? ` · ${item.error}`
                  : ''}
              </span>
            </div>
            {busy ? (
              <button
                type='button'
                onClick={() => onCancel(item.id)}
                aria-label={`Cancel ${item.name}`}
              >
                Cancel
              </button>
            ) : item.status === 'failed' || item.status === 'canceled' ? (
              <button
                type='button'
                onClick={() => onRetry(item.id)}
                aria-label={`Retry ${item.name}`}
              >
                Retry
              </button>
            ) : null}
          </li>
        );
      })}
    </ul>
  );
}

.mg-uploads {
  display: grid;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
  color: var(--mg-text, #ffffff);
}

.mg-uploads__item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px;
  border: 1px solid var(--mg-line, #303030);
  border-radius: 12px;
  background: #121212;
  animation: mg-uploads-in 260ms ease-out;
}

.mg-uploads__body {
  display: grid;
  flex: 1;
  gap: 4px;
  min-width: 0;
}

.mg-uploads__row {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: 13px;
}

.mg-uploads__row strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mg-uploads__row span,
.mg-uploads__state {
  color: #b8b8b8;
  font-size: 12px;
}

.mg-uploads__bar {
  height: 6px;
  overflow: hidden;
  border-radius: 3px;
  background: #262626;
}

.mg-uploads__bar span {
  display: block;
  height: 100%;
  background: var(--mg-accent, #eaf2fb);
  transform: scaleX(var(--mg-progress));
  transform-origin: left;
  transition: transform 260ms linear;
}

.mg-uploads__item[data-status='completed'] .mg-uploads__bar span {
  background: #eaf2fb;
}

.mg-uploads__item[data-status='failed'] .mg-uploads__bar span {
  background: #262626;
}

.mg-uploads__item[data-status='canceled'] .mg-uploads__bar span {
  background: #5c5c5c;
}

.mg-uploads__item button {
  flex: none;
  min-height: 40px;
  padding: 0 12px;
  border: 1px solid var(--mg-line-strong, #474747);
  border-radius: 8px;
  background: #121212;
  color: inherit;
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

.mg-uploads__item button:focus-visible {
  outline: 2px solid var(--mg-accent-text, #dce9f7);
  outline-offset: 2px;
}

/* Icon shapes: ring (waiting), spinner (uploading), tick, cross, bar. */
.mg-uploads__icon {
  position: relative;
  flex: none;
  width: 22px;
  height: 22px;
  border: 2px solid #5c5c5c;
  border-radius: 50%;
}

.mg-uploads__item[data-status='uploading'] .mg-uploads__icon {
  border-color: #303030;
  border-top-color: var(--mg-accent-text, #dce9f7);
  animation: mg-uploads-spin 900ms linear infinite;
}

.mg-uploads__item[data-status='completed'] .mg-uploads__icon {
  border-color: #dce9f7;
  background: #eaf2fb;
}

.mg-uploads__item[data-status='completed'] .mg-uploads__icon::after {
  position: absolute;
  top: 3px;
  left: 6px;
  width: 5px;
  height: 9px;
  border-right: 2px solid #fff;
  border-bottom: 2px solid #fff;
  content: '';
  transform: rotate(45deg);
}

.mg-uploads__item[data-status='failed'] .mg-uploads__icon {
  border-color: #ffffff;
  border-radius: 4px;
  background: #262626;
}

.mg-uploads__item[data-status='failed'] .mg-uploads__icon::after {
  position: absolute;
  inset: 0;
  color: #fff;
  content: '!';
  font-size: 13px;
  font-weight: 800;
  line-height: 18px;
  text-align: center;
}

.mg-uploads__item[data-status='canceled'] .mg-uploads__icon::after {
  position: absolute;
  top: 8px;
  left: 3px;
  width: 12px;
  height: 2px;
  background: #5c5c5c;
  content: '';
}

@keyframes mg-uploads-spin {
  to {
    transform: rotate(1turn);
  }
}

@keyframes mg-uploads-in {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-uploads__item {
    animation: none;
  }
  .mg-uploads__bar span {
    transition: none;
  }
  .mg-uploads__item[data-status='uploading'] .mg-uploads__icon {
    animation-duration: 2.4s;
  }
}
